import React from 'react';

const Team = () => {
  return (
    <div className="container mx-auto px-4 py-8">
      <h1 className="text-3xl font-bold text-gray-900">Team</h1>
      <p className="text-gray-600 mt-2">Manage your team members</p>
    </div>
  );
};

export default Team;
